/**
 * Exception types used by the scheduling library.
 *
 * Mirrors the hierarchy of the original Python package:
 *
 *   ScheduleError
 *    └── ScheduleValueError
 *         └── IntervalError
 */

/** Base scheduling exception. */
export class ScheduleError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ScheduleError';
  }
}

/** Base class for value errors during scheduling. */
export class ScheduleValueError extends ScheduleError {
  constructor(message) {
    super(message);
    this.name = 'ScheduleValueError';
  }
}

/** An improper interval was used. */
export class IntervalError extends ScheduleValueError {
  constructor(message) {
    super(message);
    this.name = 'IntervalError';
  }
}

/**
 * Sentinel. Can be returned from a job to unschedule itself, mirroring the
 * Python `CancelJob` class object that is compared by identity.
 */
export class CancelJob {}

