  ScheduleError,
  ScheduleValueError,
  IntervalError,
  CancelJob,
} from './errors.mjs';

/** The scheduler used by every module level helper below. */
export const defaultScheduler = new Scheduler();

/** Live view of the default scheduler's job list. */
export const jobs = defaultScheduler.jobs;

/** Schedule a new periodic job on the default scheduler. */
export function every(interval = 1) {
  return defaultScheduler.every(interval);
}

/** Run all jobs that are due on the default scheduler. */
export function runPending() {
  defaultScheduler.runPending();
}

/** Run all jobs on the default scheduler, regardless of their schedule. */
export function runAll(delaySeconds = 0) {
  defaultScheduler.runAll(delaySeconds);
}

/** Jobs on the default scheduler, optionally filtered by tag. */
export function getJobs(tag = null) {
  return defaultScheduler.getJobs(tag);
}

/** Delete jobs from the default scheduler, optionally only those with `tag`. */
export function clear(tag = null) {
  defaultScheduler.clear(tag);
}

/** Remove one job from the default scheduler. */
export function cancelJob(job) {
  defaultScheduler.cancelJob(job);
}

/** Instant of the next run on the default scheduler. */
export function nextRun() {
  return defaultScheduler.nextRun;
}

/** Seconds until the next run on the default scheduler. */
export function idleSeconds() {
  return defaultScheduler.idleSeconds;
}

/** Decorator-style helper: attach `func` to an already configured job. */
export function repeat(job, ...args) {
  return (func) => {
    job.do(func, ...args);
    return func;
  };
}

